// customBuild: copy pi-web-ui's pre-compiled CSS with the stylesheet matching
// our KaTeX renderer. No Tailwind JIT run is needed.

import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

const vendorDir = process.env.VENDOR_DIR;
const outPath = process.env.ENTRY_OUT_PATH;
if (!vendorDir || !outPath) {
  throw new Error("pi-web-ui-css.build: expected VENDOR_DIR and ENTRY_OUT_PATH in env");
}

const src = path.join(
  vendorDir,
  "node_modules",
  "@earendil-works",
  "pi-web-ui",
  "dist",
  "app.css"
);
const body = readFileSync(src, "utf-8");
// pi-web-ui embeds older KaTeX styles with different layout class names.
const katexCss = readFileSync(
  path.join(vendorDir, "node_modules", "katex", "dist", "katex.min.css"),
  "utf-8"
);
const header =
  "/* Copyright 2026 Dao Browser Authors. All rights reserved. */\n" +
  "/* Auto-generated by `npm run vendor -- --entry=pi-web-ui-css`. DO NOT EDIT. */\n" +
  "/* Source: @earendil-works/pi-web-ui/dist/app.css + katex/dist/katex.min.css */\n";
writeFileSync(outPath, header + body + "\n" + katexCss, "utf-8");
